# Custom Dataset class to handle corrupted images
class SafeImageFolder(torchvision.datasets.ImageFolder):
    def __getitem__(self, index):
        try:
            path, target = self.samples[index]
            sample = self.loader(path)
            if self.transform is not None:
                sample = self.transform(sample)
            if self.target_transform is not None:
                target = self.target_transform(target)
            return sample, target
        except Exception as e:
            # If loading fails, skip this sample and try the next one
            # Return another valid sample instead
            print(f"Warning: Skipping corrupted image at index {index}: {self.samples[index][0]}")
            # Try to get a different sample
            return self.__getitem__((index + 1) % len(self.samples))

